//----------------------------------------------------------------------------
// pure helper: is this an ASCII letter?
//----------------------------------------------------------------------------
#[verifier(spec)]
fn is_ascii_alpha(c: char) -> bool {
    ('a' <= c && c <= 'z') ||
    ('A' <= c && c <= 'Z')
}

